// Generated by Media Manipulator Motion
// Runtime: CSS animations (no animation library needed).

const SVG = [
  "\u003csvg xmlns=\"http://www.w3.org/2000/svg\" width=\"200\" height=\"200\" viewBox=\"0 0 200 200\"\u003e",
  "  \u003cstyle\u003e",
  "    @keyframes mm-box-transform {",
  "      0% { transform: translate(80px, 80px) rotate(0deg) scale(1, 1) translate(-20px, -20px); animation-timing-function: cubic-bezier(0.3333,0,0.6667,0.3333); }",
  "      50% { transform: translate(110px, 80px) rotate(180deg) scale(1.5, 0.75) translate(-20px, -20px); animation-timing-function: cubic-bezier(0.3333,0.6667,0.6667,1); }",
  "      100% { transform: translate(140px, 80px) rotate(360deg) scale(2, 0.5) translate(-20px, -20px); }",
  "    }",
  "    @keyframes mm-box-opacity {",
  "      0% { opacity: 1; animation-timing-function: linear; }",
  "      100% { opacity: 0.4; }",
  "    }",
  "    @keyframes mm-box-fill {",
  "      0% { fill: #3b82f6; animation-timing-function: linear; }",
  "      100% { fill: #ef4444; }",
  "    }",
  "    #box {",
  "      animation-name: mm-box-transform, mm-box-opacity, mm-box-fill;",
  "      animation-duration: 2000ms;",
  "      animation-timing-function: linear;",
  "      animation-iteration-count: infinite;",
  "      animation-fill-mode: both;",
  "      transform-box: view-box;",
  "      transform-origin: 0 0;",
  "    }",
  "  \u003c/style\u003e",
  "  \u003crect id=\"box\" x=\"0\" y=\"0\" width=\"40\" height=\"40\" fill=\"#3b82f6\" opacity=\"1\" transform=\"translate(60 60)\"/\u003e",
  "\u003c/svg\u003e",
].join('\n');

let svg: SVGSVGElement | null = null;

/** Append the animation to el (replacing a previously mounted instance) and return the <svg>. */
export function mount(el: Element): SVGSVGElement {
  unmount();
  const parsed = new DOMParser().parseFromString(SVG, 'image/svg+xml');
  const node = document.importNode(parsed.documentElement, true) as unknown as SVGSVGElement;
  el.appendChild(node);
  svg = node;
  return node;
}

function unmount(): void {
  if (svg && svg.parentNode) svg.parentNode.removeChild(svg);
  svg = null;
}

function animations(): Animation[] {
  return svg ? svg.getAnimations({ subtree: true }) : [];
}

export function play(): void {
  for (const a of animations()) a.play();
}

export function pause(): void {
  for (const a of animations()) a.pause();
}

export function seek(ms: number): void {
  for (const a of animations()) a.currentTime = ms;
}
